#!/usr/bin/env python3
"""Compile authentic pinned WorldMapOverlay area joins from local CASC, never inferred IDs."""
import argparse
import hashlib
from pathlib import Path

import db2_casc


def generate(source, output):
    data = source.read_bytes()
    header, rows = db2_casc.decode(data)
    if header["layout_hash"] != 0x9A196494:
        raise ValueError("WorldMapOverlay requires 12.1.0.69933 layout 9A196494")
    lines = [
        "// Generated by scripts/gen_achievement_overlays.py; do not edit.",
        "// WoWDBDefs WorldMapOverlay layout9A196494, build12.1.0.69933, FDID1134579.",
        f"// Local DB2 SHA256 {hashlib.sha256(data).hexdigest()}",
        "pub fn areas(overlay: u32) -> Option<[u32; 4]> {",
        "    Some(match overlay {",
    ]
    for overlay, row in sorted(rows.items()):
        if len(row) != 17 or row[0] != overlay:
            raise ValueError(f"WorldMapOverlay {overlay}: unexpected field count/order")
        # Non-inline UiMapArtID is expanded before fields and at the relation tail.
        areas = row[12:16]
        lines.append(f"        {overlay} => [{', '.join(map(str, areas))}],")
    lines.extend(["        _ => return None,", "    })", "}", ""])
    output.write_text("\n".join(lines))
    print(f"WorldMapOverlay: {len(rows)} authentic joins -> {output}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    generate(args.source, args.output)
